#[derive(serde::Serialize)]
pub struct Pong {
    pub message: String,
}

pub fn build_pong(name: &str) -> Result<Pong, String> {
    if name.trim().is_empty() {
        return Err(String::from("validation: name required"));
    }
    Ok(Pong { message: format!("pong, {name}") })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_empty() {
        assert!(build_pong(" ").is_err());
        assert_eq!(build_pong("vue").unwrap().message, "pong, vue");
    }
}
